}) }}

parameters.jsCode:
// LLM 응답 (JSON 문자열) 파싱
const raw = String($input.first().json.choices?.[0]?.message?.content ?? '').trim().replace(/^```(json)?\s*|```$/g, '');
let data;
try {
  data = JSON.parse(raw);
} catch (error) {
  return [{
    json: {
      title: $('Settings').first().json.title || '회의록',
      route: '오류',
      count: 0,
      summary: 'LLM 응답을 JSON으로 파싱할 수 없습니다.',
      actions: [],
      report_text: `[오류] LLM 응답이 올바른 JSON 형식이 아닙니다.\n원본: ${raw}`
    }
  }];
}

const settings = $('Settings').first().json;
const title = String(settings.title || '회의록').trim();

// 요약(summary) 정리
const summary = String(data.summary || '').trim() || '회의 요약이 없습니다.';

// null 및 빈값 정제 헬퍼 함수
function sanitizeField(val) {
  if (val === null || val === undefined) return null;
  const s = String(val).trim();
  if (!s || s === 'null' || s === 'undefined' || s === '미정' || s === '없음' || s === '-' || s === 'N/A') {
    return null;
  }
  return s;
}

// 우선순위(priority) 판별 헬퍼 함수
function determinePriority(task, due) {
  const combined = `${task || ''} ${due || ''}`.toLowerCase();
  if (/오늘|당일|금일|긴급|즉시|asap|urgent|today/.test(combined)) {
    return '높음';
  }
  return '보통';
}

// 할 일 목록 정리
const rawActions = Array.isArray(data.actions) ? data.actions : [];
const actions = [];

for (const item of rawActions) {
  if (!item) continue;
  const task = String(item.task ?? '').trim();
  if (!task) continue;

  const owner = sanitizeField(item.owner);
  const due = sanitizeField(item.due);
  const priority = determinePriority(task, due);

  actions.push({
    task,
    owner,
    due,
    priority
  });
}

const count = actions.length;
const route = count > 0 ? '할 일 정리' : '할 일 없음';

// report_text 생성
const actionLines = actions.map((a, i) => {
  const ownerText = a.owner ? a.owner : '담당자 미정';
  const dueText = a.due ? a.due : '기한 미정';
  return `${i + 1}. [${a.priority}] ${a.task} - ${ownerText} (${dueText})`;
});

const reportText = count > 0
  ? `${title}\n${summary}\n\n[할 일 목록]\n${actionLines.join('\n')}`
  : `${title}\n${summary}\n\n[할 일 목록]\n(할 일 없음)`;

return [{
  json: {
    title,
    route,
    count,
    summary,
    actions,
    report_text: reportText
  }
}];
